using System.Net;
using System.Net.Http.Headers;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.Hosting.Server;
using Microsoft.AspNetCore.Hosting.Server.Features;
using Microsoft.Extensions.DependencyInjection;
using WindowsIntelligence.SkillRelay;
using WindowsIntelligence.Xiaomi;

void Need(bool condition, string error) { if (!condition) throw new InvalidOperationException(error); }
// Exact published Xiaomi POST signature fixture, not a signature generated by
// the same verifier under test. The key here is the public documentation dummy.
var vector = XiaomiSignature.Sign(Convert.FromBase64String("xxxxxxxxxxxxxxxxyyyyyyyyyyyyyyyy"), "abcde",
    XiaomiSignature.Canonical("/hmac/testPost", "Mon, 7 Aug 2017 08:02:03 GMT", "localhost:19001",
        "application/x-www-form-urlencoded", "LvICVZWSXkBmN8URxZ1wlg=="));
Need(vector.EndsWith("7af664ac15b675633bc13a3ab03adc2d0c6e3834999785698e5830ae215a8545"), "Official signature vector mismatch");
var temp = Directory.CreateTempSubdirectory("wi-skill-relay-test-");
var options = new RelayOptions("test-app", "test-key", RandomNumberGenerator.GetBytes(32), new string('T', 48),
    "paired-user", "paired-device", "skill.example.test", temp.FullName, true);
await using var app = RelayHost.Build(options); app.Urls.Add("http://127.0.0.1:0");
await app.StartAsync();
var address = app.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>()!.Addresses.Single();
using var http = new HttpClient { BaseAddress = new(address), Timeout = TimeSpan.FromSeconds(10) };
var jsonOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);
byte[] Body(string id, string query = "查询电脑内存占用", string user = "paired-user", string previous = "") =>
    JsonSerializer.SerializeToUtf8Bytes(new { version = "1.0", query,
        session = new { session_id = "session-test", application = new { app_id = options.AppId },
            user = new { user_id = user }, attributes = new { wi_job_id = previous } },
        context = new { device_id = options.DeviceId }, request = new { request_id = id, type = 1,
            timestamp = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() } });
HttpRequestMessage Signed(byte[] body, bool tamper = false, bool md5 = true)
{
    string date = DateTimeOffset.UtcNow.ToString("r"), digest = Convert.ToBase64String(MD5.HashData(body));
    var req = new HttpRequestMessage(HttpMethod.Post, "xiaomi/skill") { Content = new ByteArrayContent(body) };
    req.Content.Headers.ContentType = new MediaTypeHeaderValue("application/json");
    req.Headers.TryAddWithoutValidation("X-Xiaomi-Date", date);
    req.Headers.TryAddWithoutValidation("x-original-host", options.PublicHost);
    if (md5) req.Content.Headers.TryAddWithoutValidation("Content-MD5", digest);
    req.Headers.TryAddWithoutValidation("Authorization", XiaomiSignature.Sign(options.Secret, options.KeyId,
        XiaomiSignature.Canonical("/xiaomi/skill", date, options.PublicHost, "application/json", digest)));
    if (tamper) req.Content = new StringContent(Encoding.UTF8.GetString(body).Replace("内存", "硬盘"), Encoding.UTF8, "application/json");
    return req;
}
async Task<HttpResponseMessage> Windows(string path, object payload)
{
    using var req = new HttpRequestMessage(HttpMethod.Post, path) { Content = new StringContent(JsonSerializer.Serialize(payload, jsonOptions), Encoding.UTF8, "application/json") };
    req.Headers.Authorization = new("Bearer", options.WindowsToken); return await http.SendAsync(req);
}
try
{
    using (var bad = await http.SendAsync(Signed(Body("tamper"), tamper: true))) Need(bad.StatusCode == HttpStatusCode.Unauthorized, "Tampered body accepted");
    using (var bad = await http.SendAsync(Signed(Body("no-md5"), md5: false))) Need(bad.StatusCode == HttpStatusCode.Unauthorized, "Unbound body accepted");
    using (var bad = await http.SendAsync(Signed(Body("wrong-owner", user: "unpaired")))) Need(bad.StatusCode == HttpStatusCode.Unauthorized, "Unpaired owner accepted");
    var payload = Body("request-1");
    var callback = http.SendAsync(Signed(payload));
    WindowsTask? task = null;
    for (int i = 0; i < 20 && task is null; i++)
    {
        using var response = await Windows("v1/windows/lease", new { });
        if (response.StatusCode == HttpStatusCode.OK) task = JsonSerializer.Deserialize<WindowsTask>(await response.Content.ReadAsStringAsync(), jsonOptions);
        else await Task.Delay(30);
    }
    Need(task is not null && task.Query == "查询电脑内存占用", "Windows did not receive the task");
    using (var again = await Windows("v1/windows/lease", new { })) Need(again.StatusCode == HttpStatusCode.NoContent, "Lease redelivered");
    var result = new WindowsTaskResult(task!.JobId, task.Lease, "completed", "内存查询完成，示例结果为百分之四十二。");
    using (var response = await Windows("v1/windows/result", result)) Need(response.IsSuccessStatusCode, "Result rejected");
    using (var response = await callback)
    {
        using var reply = JsonDocument.Parse(await response.Content.ReadAsStringAsync());
        Need(reply.RootElement.GetProperty("response").GetProperty("to_speak").GetProperty("text").GetString() == result.Reply,
            "XiaoAI did not receive the Windows result");
    }
    using (var replay = await http.SendAsync(Signed(payload))) Need(replay.IsSuccessStatusCode, "Idempotent callback failed");
    using (var again = await Windows("v1/windows/lease", new { })) Need(again.StatusCode == HttpStatusCode.NoContent, "Replay caused a second execution");
    using (var status = await http.SendAsync(Signed(Body("result-query", "查看结果", previous: task.JobId))))
        Need((await status.Content.ReadAsStringAsync()).Contains("四十二"), "Status query lost the result");
    using (var slow = await http.SendAsync(Signed(Body("slow-request"))))
        Need((await slow.Content.ReadAsStringAsync()).Contains("正在电脑上处理"), "Slow task was falsely reported complete");
    var persisted = new RelayStore(temp.FullName);
    Need(persisted.Lease(DateTimeOffset.UtcNow) is null, "Server restart reran unfinished work");
    Console.WriteLine("PASS official HMAC vector, authenticated callback -> Windows lease -> native to_speak reply, replay, owner isolation and restart policy.");
}
finally
{
    await app.StopAsync();
    var verified = Path.GetFullPath(temp.FullName);
    if (Path.GetDirectoryName(verified) == Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar) &&
        Path.GetFileName(verified).StartsWith("wi-skill-relay-test-", StringComparison.Ordinal)) Directory.Delete(verified, true);
}
